public static int winnerPoints(int[] codes, int[] points, int code) {
    int max = -1;   // נשאר -1 אם אין אף קבוצה משכבת הגיל הזו
    for (int i = 0; i < codes.length; i++) {
        if (codes[i] == code && points[i] > max) {
            max = points[i];
        }
    }
    return max;
}

